1	//! The `kata` command line adapter: it reads a scenario as JSON on stdin and
2	//! writes the MHPCO's results as JSON on stdout. All insurance decisions belong
3	//! to the library; this binary only translates and reports failures.
4	
5	use std::io::{Read, Write};
6	use std::process::ExitCode;
7	
8	use kata::{process_scenario, results_to_json, scenario_from_json};
9	
10	fn main() -> ExitCode {
11	    match run() {
12	        Ok(results) => {
13	            println!("{results}");
14	            ExitCode::SUCCESS
15	        }
16	        Err(description) => {
17	            let _ = writeln!(std::io::stderr(), "{description}");
18	            ExitCode::FAILURE
19	        }
20	    }
21	}
22	
23	fn run() -> Result<String, String> {
24	    let mut stdin = String::new();
25	    std::io::stdin()
26	        .read_to_string(&mut stdin)
27	        .map_err(|error| error.to_string())?;
28	    let scenario = scenario_from_json(&stdin).map_err(|error| error.to_string())?;
29	    let results = process_scenario(&scenario).map_err(|error| error.to_string())?;
30	    results_to_json(&results).map_err(|error| error.to_string())
31	}
